const TRACK_COL = "WI Created on EasyBOP";
const api_base_url = "http://173.212.233.153:8000";
// Must read the sheet node by name — $input.all() only sees 1 item here
const rows = $('Read Work Inst Import').all().map((i) => i.json || {});
function pickCorf(row) {
  const v = row['Client Order Reference'] ?? row['Client Order Ref'] ?? row['Client Order Ref.'];
  const s = String(v ?? '').trim();
  if (!s || /^client order ref/i.test(s)) return '';
  return s;
}
function notYetCreated(row) {
  const v = row[TRACK_COL];
  if (v === null || v === undefined) return true;
  const s = String(v).trim().toLowerCase();
  if (!s) return true;
  if (s === 'false' || s === '0' || s === 'no') return true;
  return false;
}
const pending = rows.filter((r) => pickCorf(r) && notYetCreated(r));
if (!pending.length) {
  return [{
    json: {
      has_pending_wi: false,
      pending_count: 0,
      message: 'No unprocessed rows (all marked or empty)',
    },
  }];
}
// Single item with ALL pending rows — one API call processes every CORF
return [{
  json: {
    has_pending_wi: true,
    pending_count: pending.length,
    api_base_url,
    contract_id: '321129',
    rows: pending,
    message: pending.length + ' row(s) to create on EasyBOP',
  },
}];

const api = $input.first().json || {};
function markFromResult(r) {
  return {
    json: {
      'Client Order Reference': r.client_order_reference,
      "WI Created on EasyBOP": 'TRUE',
      _row_number: r.row_number ?? null,
    },
  };
}
const results = Array.isArray(api.results) ? api.results : [];
if (api.error) {
  const partial = results.filter((r) => r && r.success).map(markFromResult);
  if (partial.length) return partial;
  return [{
    json: {
      _skip_mark: true,
      message: String(api.error.message || api.error),
    },
  }];
}
const marks = results.filter((r) => r && r.success).map(markFromResult);
if (!marks.length) {
  return [{
    json: {
      _skip_mark: true,
      message: api.detail || api.message || 'No works instructions created',
      created_count: api.created_count || 0,
      failed_count: api.failed_count || 0,
    },
  }];
}
return marks;

const rows = $('Read BOQ Import').all().map((i) => i.json || {});
const has = rows.some((r) => String(r['BOQ Item Ref.'] ?? '').trim());
return [{ json: { has_boq_rows: has, boq_row_count: rows.length } }];

const exportRows = $('Read xlsx rows (works list)').all().map((i) => i.json || {});
const WI_COL = 'Works Instruction Ref.';
const CORF_COLS = ['CORF', 'corf', 'Client Order Reference'];

function normCorf(v) {
  const raw = String(v ?? '').trim();
  if (!raw || /^client order ref/i.test(raw)) return '';
  const t = raw.toLowerCase().replace(/\s+/g, '');
  const slash = t.match(/^(\d+)\/(\d+)$/);
  if (slash) return parseInt(slash[1], 10) + '/' + parseInt(slash[2], 10);
  const digits = t.replace(/\D/g, '');
  if (digits.length >= 4) return String(parseInt(digits, 10));
  return t;
}

function pickCorf(row) {
  for (const col of CORF_COLS) {
    const k = normCorf(row[col]);
    if (k) return k;
  }
  const wi = normCorf(row[WI_COL]);
  if (wi) {
    const m = wi.match(/^(\d+)\//);
    if (m && parseInt(m[1], 10) >= 10000) return wi;
  }
  return '';
}

const corfToWi = {};
for (const row of exportRows) {
  const corf = normCorf(row['Client Order Reference']);
  const wi = String(row['Our Works Instruction Number'] ?? '').trim();
  if (corf && wi) corfToWi[corf] = wi;
}

const out = [];
let skippedNoCorf = 0;
let skippedNoMatch = 0;
let skippedOk = 0;

for (const item of $('Read BOQ Import').all()) {
  const row = item.json || {};
  const rowNum = row.row_number ?? row.__rowNumber ?? null;
  if (rowNum == null) continue;
  const corf = pickCorf(row);
  if (!corf) { skippedNoCorf++; continue; }
  const wiRef = corfToWi[corf];
  if (!wiRef) { skippedNoMatch++; continue; }
  const cur = String(row[WI_COL] ?? '').trim();
  if (cur === wiRef) { skippedOk++; continue; }
  out.push({
    json: {
      ...row,
      [WI_COL]: wiRef,
      _row_number: rowNum,
      _corf_matched: corf,
      _works_instruction_ref_before: cur || null,
      _works_instruction_ref_after: wiRef,
    },
  });
}

if (!out.length) {
  return [{
    json: {
      _skip_boq_ref_update: true,
      _message: 'No BOQ rows need Works Instruction Ref update (CORF match)',
      _skipped_no_corf: skippedNoCorf,
      _skipped_no_match: skippedNoMatch,
      _skipped_already_ok: skippedOk,
    },
  }];
}
return out;

const UPLOAD_COLS = [
  'Works Instruction Ref.',
  'Works Instruction Address',
  'BOQ Item Name',
  'BOQ Item Section Name',
  'BOQ Item Ref.',
  'BOQ Item Short Description',
  'BOQ Item Unit',
  'BOQ Item Rate',
  'Quantity',
  'Location',
  'Notes',
];

function looksLikeWiRef(v) {
  const s = String(v ?? '').trim();
  if (!s) return false;
  const m = s.match(/^(\d+)\/(\d+)$/);
  if (!m) return false;
  return parseInt(m[1], 10) < 10000;
}

const rows = $('Read BOQ Import for upload').all().map((i) => i.json || {});
const valid = rows.filter((r) => {
  const ref = String(r['BOQ Item Ref.'] ?? '').trim();
  return ref && looksLikeWiRef(r['Works Instruction Ref.']);
});

if (!valid.length) {
  return [{ json: { _skip_boq_upload: true, _message: 'No valid BOQ rows to upload' } }];
}

return [{
  json: {
    rows: valid.map((r) => {
      const o = {};
      for (const c of UPLOAD_COLS) o[c] = r[c] ?? null;
      return o;
    }),
    row_count: valid.length,
  },
}];

const uploadResp = $input.first().json || {};
if (uploadResp.error) {
  return [{
    json: {
      _skip_boq_mark: true,
      message: String(uploadResp.error.message || uploadResp.error),
    },
  }];
}

const CORF_COLS = ['CORF', 'corf', 'Client Order Reference'];
const WI_CORF_COLS = ['Client Order Reference', 'Client Order Ref', 'Client Order Ref.'];

function normCorf(v) {
  const raw = String(v ?? '').trim();
  if (!raw || /^client order ref/i.test(raw)) return '';
  const t = raw.toLowerCase().replace(/\s+/g, '');
  const slash = t.match(/^(\d+)\/(\d+)$/);
  if (slash) return parseInt(slash[1], 10) + '/' + parseInt(slash[2], 10);
  const digits = t.replace(/\D/g, '');
  if (digits.length >= 4) return String(parseInt(digits, 10));
  return t;
}

function pickBoqCorf(row) {
  for (const col of CORF_COLS) {
    const k = normCorf(row[col]);
    if (k) return k;
  }
  return '';
}

function pickWiCorf(row) {
  for (const col of WI_CORF_COLS) {
    const k = normCorf(row[col]);
    if (k) return k;
  }
  return '';
}

function looksLikeWiRef(v) {
  const s = String(v ?? '').trim();
  if (!s) return false;
  const m = s.match(/^(\d+)\/(\d+)$/);
  if (!m) return false;
  return parseInt(m[1], 10) < 10000;
}

const boqRows = $('Read BOQ Import for upload').all().map((i) => i.json || {});
const uploadedCorfs = new Set();
for (const row of boqRows) {
  const ref = String(row['BOQ Item Ref.'] ?? '').trim();
  if (!ref || !looksLikeWiRef(row['Works Instruction Ref.'])) continue;
  const corf = pickBoqCorf(row);
  if (corf) uploadedCorfs.add(corf);
}

if (!uploadedCorfs.size) {
  return [{
    json: {
      _skip_boq_mark: true,
      message: 'No CORFs to mark after BOQ upload',
    },
  }];
}

const wiRows = $('Read Work Inst Import').all().map((i) => i.json || {});
const marks = [];
for (const row of wiRows) {
  const corf = pickWiCorf(row);
  if (!corf || !uploadedCorfs.has(corf)) continue;
  marks.push({
    json: {
      'Client Order Reference': row['Client Order Reference'] ?? corf,
      'BOQ Uploaded': 'TRUE',
      _row_number: row.row_number ?? row._row_number ?? null,
      _corf: corf,
    },
  });
}

if (!marks.length) {
  return [{
    json: {
      _skip_boq_mark: true,
      message: 'No matching Work Inst Import rows for uploaded BOQ CORFs',
    },
  }];
}
return marks;
